import React from 'react';

export default function TaskList({ tasks, onEdit, onDelete, auth }){
  return (
    <div>
      <h4>Tasks ({tasks.length})</h4>
      {tasks.map(t => (
        <div 
          key={t._id} 
          style={{ 
            border: '1px solid #ddd', 
            padding: 12, 
            marginBottom: 12, 
            borderRadius: '6px', /* Soft corners */
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)', /* Subtle shadow */
            backgroundColor: 'white' /* Clean white background */
          }}
        >
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <strong className="task-title" style={{ fontSize: '1.1em', color: '#00796B' }}>{t.title}</strong>
            <small style={{ color: '#555' }}>
              Progress: <span style={{ fontWeight: 'bold' }}>{t.progress}</span> {t.dueDate ? `| due ${new Date(t.dueDate).toLocaleDateString()}` : ''}
            </small>
          </div>
          <div style={{ marginTop: 4, marginBottom: 8, color: '#444' }}>{t.description}</div>
          <div style={{ marginTop: 6 }}>
            {auth && auth.id === t.userId && (
              <>
                <button onClick={()=>onEdit(t)}>Edit</button>
                <button onClick={()=>onDelete(t._id)} style={{ backgroundColor: '#D32F2F' }}>Delete</button>
              </>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}
